describe('Returning User Login - Secure Area Access', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should successfully log in a returning user and access secure area', () => {
    cy.get('[data-testid="username-input"]').type('tomsmith');
    cy.get('[data-testid="password-input"]').type('SuperSecretPassword!');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/secure');
    cy.get('[data-testid="success-flash"]').should('be.visible');
    cy.get('[data-testid="success-flash"]').should('contain', 'You logged into a secure area!');
    cy.get('[data-testid="secure-content"]').should('be.visible');
    cy.get('[data-testid="secure-content"]').should('contain', 'This is a secure page');
  });

  it('should display error message when login fails with invalid credentials', () => {
    cy.get('[data-testid="username-input"]').type('tomsmith');
    cy.get('[data-testid="password-input"]').type('WrongPassword');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/login');
    cy.get('[data-testid="error-flash"]').should('be.visible');
    cy.get('[data-testid="error-flash"]').should('contain', 'Invalid username or password');
    cy.get('[data-testid="secure-content"]').should('not.exist');
  });
});
